<script setup lang="ts">import { computed, ref } from 'vue'; import { useRoute, RouterLink } from 'vue-router'; import { ArrowLeft, Check, CircleCheck } from 'lucide-vue-next'; import { modules, questions } from '../data'; import { done, toggleDone } from '../composables'; const route=useRoute(); const mod=computed(()=>modules.find(m=>m.id===route.params.id)!); const qs=computed(()=>questions[route.params.id as string]||[]); const current=ref(0); const selected=ref<number|null>(null); const finished=ref(false); function answer(i:number){if(selected.value===null)selected.value=i} function next(){if(current.value<qs.value.length-1){current.value++;selected.value=null}else{finished.value=true;toggleDone(mod.value.id)}} function reset(){current.value=0;selected.value=null;finished.value=false}</script>
<template><div class="page"><div class="container"><RouterLink to="/aprender" class="muted" style="text-decoration:none"><ArrowLeft :size="15"/> Voltar para a trilha</RouterLink><div class="module-layout"><aside class="side-list"><RouterLink v-for="m in modules" :key="m.id" :to="'/modulo/'+m.id">{{m.number}} · {{m.title}}</RouterLink></aside><article><div class="eyebrow">Módulo {{mod.number}}</div><h1>{{mod.title}}</h1><p class="muted">{{mod.short}}</p><div v-for="(lesson,i) in mod.lessons" :key="lesson" class="lesson"><h2>{{i+1}}. {{['O essencial','Na prática','Para levar com você'][i]}}</h2><p>{{lesson}}</p></div><div class="tips"><div v-for="tip in mod.tips" :key="tip" class="tip"><Check :size="15"/> {{tip}}</div></div><div class="panel quiz" style="margin-top:38px"><template v-if="!finished"><div class="eyebrow">Revisão rápida · {{current+1}} de {{qs.length}}</div><h2>{{qs[current].q}}</h2><label v-for="(option,i) in qs[current].options" :key="option" :class="['quiz-option',{selected:selected===i}]"><input type="radio" :value="i" v-model="selected" @change="answer(i)" hidden/>{{option}}</label><div v-if="selected!==null" class="feedback">{{selected===qs[current].answer?'Boa! ':'Quase. '}}{{qs[current].explain}}</div><button class="button primary" style="margin-top:18px" :disabled="selected===null" @click="next">{{current===qs.length-1?'Concluir módulo':'Próxima pergunta'}}</button></template><template v-else><CircleCheck :size="42" color="#32a86b"/><h2>Módulo concluído.</h2><p class="muted">Você pode refazer a revisão quando quiser. Seu progresso fica salvo neste navegador.</p><button class="button secondary" @click="reset">Refazer revisão</button></template></div></article></div></div></div></template>
